static constexpr uint32_t ARM_AINPUTQUEUE     = 0xC0FEBE10u; /* opaque AInputQueue* */
static constexpr uint32_t ARM_AINPUTEVENT     = 0xC0FEBE11u; /* opaque AInputEvent* */

