        if (!r0) { ret32((uint32_t)-1); break; }
        g_aaudio_builder = AAudioStreamState{};   /* reset accumulated config */
        ctx.mem.write32(r0, ARM_AAUDIO_BUILDER);
        ret32(0u); break;
