        case 5u:  next = 6u;  break;   /* PAUSING -> PAUSED */
        case 7u:  next = 8u;  break;   /* FLUSHING -> FLUSHED */
        case 9u:  next = 10u; break;   /* STOPPING -> STOPPED */
        case 11u: next = 12u; break;   /* CLOSING -> CLOSED */
