            case 16u: v = 0x000000FFu; break; /* AT_HWCAP: through CRC32 */
            case 26u: v = 0u; break;          /* AT_HWCAP2 */
            case 6u:  v = 4096u; break;       /* AT_PAGESZ */
            default:  v = 0u; break;
