    case SVC_EGL_SURFACEATTRIB: {
        /* eglSurfaceAttrib(dpy, surface, attr, value).  EGL_TIMESTAMPS_ANDROID
         * is the switch that makes eglGetFrameTimestampsANDROID legal; the
         * previous always-TRUE stub swallowed it and the queries then failed. */
        EGLint attr = (EGLint)r2;
        EGLint value = (EGLint)r3;
        if (attr == EGL_TIMESTAMPS_ANDROID_ATTR) {
            g_egl_timestamps_enabled = (value != EGL_FALSE);
            static int ts_attr_log = 0;
            if (ts_attr_log++ < 4)
                fprintf(stderr, "[egl] SurfaceAttrib(TIMESTAMPS_ANDROID, %d) tid=%u\n",
                        (int)value, g_current_tid);
            egl_set_guest_error(EGL_SUCCESS);
            ret32(EGL_TRUE);
            break;
        }
        EGLBoolean ok = EGL_TRUE;
        if (g_egl_dpy != EGL_NO_DISPLAY && g_egl_surf != EGL_NO_SURFACE)
            ok = eglSurfaceAttrib(g_egl_dpy, g_egl_surf, attr, value);
        ret32((uint32_t)ok);
        break;
    }
    case SVC_EGL_GETCURCTX: {
        uint32_t cur = egl_host_current_context();
        if (lunaria_env("LUNARIA_TRACE_EGL")) {
            static int n = 0;
            if (n++ < 40)
                fprintf(stderr, "[egl] getCurrentContext -> 0x%x tid=%u lr=0x%08x\n",
                        cur, g_current_tid, lr);
        }
        ret32(cur);
        break;
    }
    case SVC_EGL_GETCURSURF:
        ret32(egl_surf_for_tid(g_current_tid)); break;

    // eglGetSystemTimeFrequencyNV() -> uint64_t ticks-per-second.
    case SVC_EGL_SYSTIME_FREQ: {
        static int stf_log = 0;
        if (stf_log++ < 3)
            fprintf(stderr, "[egl] eglGetSystemTimeFrequencyNV() -> 1000000000\n");
        ret64(1000000000ull);
        break;
    }
    // eglGetSystemTimeNV() -> uint64_t nanoseconds since boot
    case SVC_EGL_SYSTIME: {
        struct timespec ts = {};
        ret64(host_mono_ns());
        break;
    }

    case SVC_SIGEMPTYSET:
    case SVC_SIGFILLSET: {
        GuestVA set_va = argp(0);
        if (!set_va) {
            if (uint32_t eva = errno_va(ctx, g_current_tid))
                ctx.mem.write32(eva, EFAULT);
            ret32(~0u);
            break;
        }
        ctx.mem.write64(set_va, svc_no == SVC_SIGFILLSET ? ~0ull : 0ull);
        ret32(0);
        break;
    }
    case SVC_SIGADDSET:
    case SVC_SIGDELSET: {
        GuestVA set_va = argp(0);
        int sig = (int)r1;
        if (!set_va || sig <= 0 || sig > 64) {
            if (uint32_t eva = errno_va(ctx, g_current_tid))
                ctx.mem.write32(eva, set_va ? EINVAL : EFAULT);
            ret32(~0u);
            break;
        }
        uint64_t set = ctx.mem.read64(set_va);
        uint64_t bit = 1ull << (unsigned)(sig - 1);
        set = svc_no == SVC_SIGADDSET ? (set | bit) : (set & ~bit);
        ctx.mem.write64(set_va, set);
        ret32(0);
        break;
    }
    case SVC_SIGISMEMBER: {
        GuestVA set_va = argp(0);
        int sig = (int)r1;
        if (!set_va || sig <= 0 || sig > 64) {
            if (uint32_t eva = errno_va(ctx, g_current_tid))
                ctx.mem.write32(eva, set_va ? EINVAL : EFAULT);
            ret32(~0u);
            break;
        }
        uint64_t set = ctx.mem.read64(set_va);
        ret32((set & (1ull << (unsigned)(sig - 1))) ? 1u : 0u);
        break;
    }

    /* sigsuspend(mask) atomically installs the temporary mask and parks this
     * guest thread.  A later signal makes it runnable; delivery records the
     * -1/EINTR return in the interrupted ucontext and restores the old mask. */
    case SVC_SIGSUSPEND: {
        static int ss_log = 0;
        if (ctx.is_arm64) {
            ArmThread *t = arm_thread_by_tid(g_current_tid);
            if (t) {
                const GuestVA set_va = argp(0);
                uint64_t mask = set_va ? ctx.mem.read64(set_va) : 0;
                mask &= ~(1ull << (9 - 1));
                mask &= ~(1ull << (19 - 1));
                t->sigsuspend_old_mask = signal_mask_load(t->id);
                signal_mask_store(t->id, mask);
                t->waiting_signal = true;
                if (uint32_t eva = errno_va(ctx, t->id)) ctx.mem.write32(eva, EINTR);
                ret32(~0u);
                g_yield_requested = true;
                if (ss_log++ < 8)
                    fprintf(stderr, "[sigsuspend] parked tid=%u mask=0x%llx\n",
                            t->id, (unsigned long long)mask);
                break;
            }
        }
        if (ss_log++ < 5)
            fprintf(stderr, "[sigsuspend] r0=0x%08lx tid=%u -> -1/EINTR\n", r0, g_current_tid);
        uint32_t eva = errno_va(ctx, g_current_tid);
        if (eva) ctx.mem.write32(eva, 4 /* EINTR */);
        ret32(~0u); break;
    }

    // dl_unwind_find_exidx(pc, *pcount):.
    case SVC_DL_UNWIND_EXIDX: {
        static int dl_call_count = 0;
        uint32_t hit_va = 0, hit_count = 0;
        for (const auto &m : g_module_exidx)
            if (r0 >= m.lo && r0 < m.hi)
                { hit_va = m.exidx_va; hit_count = m.exidx_count; break; }
        if (dl_call_count < 8)
            fprintf(stderr, "[arm_exec] dl_unwind_find_exidx pc=0x%08lx -> "
                    "exidx=0x%08x count=%u (call %d)\n",
                    r0, hit_va, hit_count, ++dl_call_count);
        else ++dl_call_count;
        if (hit_va) {
            if (r1) ctx.mem.write32(r1, hit_count);
            ret32(hit_va);
            break;
        }
        // Lazy-allocate a 2-word ARM buffer for the fake EXIDX entry
        static uint32_t fake_exidx_va = 0;
        if (!fake_exidx_va) {
            fake_exidx_va = arm_malloc(ctx, 8);
            // word0: PREL31(entry_addr -> 0).  Any PC ≥ 0 will match this entry.
            uint32_t prel31 = (uint32_t)(-(int32_t)fake_exidx_va) & 0x7FFFFFFFu;
            ctx.mem.write32(fake_exidx_va,     prel31);
            ctx.mem.write32(fake_exidx_va + 4, 0x00000001u); /* CANTUNWIND */
        }
        if (r1) ctx.mem.write32(r1, 1u); /* pcount = 1 */
        ret32(fake_exidx_va);
        break;
    }

    // ---- OpenGL ES 2.0 ----
    // Helper to read host pointer from ARM VA (for data buffers)
#define ARM_PTR(va) ((va) ? (void*)ctx.mem.ptr(va) : nullptr)
#define ARM_CPTR(va) ((va) ? (const void*)ctx.mem.ptr(va) : nullptr)
#define ARM_STR_GL(va) ((va) ? ctx.mem.cstr(va) : nullptr)

    case SVC_GL_Viewport:
        { static int n=0; if(n<3) fprintf(stderr,"[gl] glViewport(%d,%d,%d,%d) tid=%u\n",(int)r0,(int)r1,(int)r2,(int)r3,g_current_tid); ++n; }
        g_gl_last_viewport[0]=(int)r0; g_gl_last_viewport[1]=(int)r1;
        g_gl_last_viewport[2]=(int)r2; g_gl_last_viewport[3]=(int)r3;
        if (pfn_glViewport) pfn_glViewport((GLint)r0,(GLint)r1,(GLsizei)r2,(GLsizei)r3);
        break;
    case SVC_GL_Clear:
        ++g_guest_gl_clear_count;
