            if (type_va) ctx.mem.write32(type_va,(uint32_t)tp);
            if (name_va) if (auto *p = ctx.mem.ptr(name_va)) memcpy(p,buf.data(),std::min<GuestVA>((uint32_t)len+1,r2));
