                ctx.mem.write32(pw + 2 * W + 4, uid);                /* pw_gid    */
                guest_net::put_ptr(ctx, pw + 2 * W + 8, guest_net::guest_ptr(ctx, em));    /* pw_gecos  */
                guest_net::put_ptr(ctx, pw + 3 * W + 8, guest_net::guest_ptr(ctx, hd));    /* pw_dir    */
